import{z as o,x as n,o as A,c as i,q as t,j as B,D as a,d as e,s,S as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"自博弈深化的边界与收束","description":"","frontmatter":{"title":"自博弈深化的边界与收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-map.md","filePath":"llm/sgt-map.md","lastUpdated":1791063341000}'),C={name:"llm/sgt-map.md"};function p(d,E,F,D,h,m){const r=n("Mermaid");return A(),i("div",null,[E[2]||(E[2]=t('<h1 id="自博弈深化的边界与收束" tabindex="-1">自博弈深化的边界与收束 <a class="header-anchor" href="#自博弈深化的边界与收束" aria-label="Permalink to &quot;自博弈深化的边界与收束&quot;">​</a></h1><div class="epigraph"><p>自博弈的价值不在于「模型跟自己打会变强」，而在于它把一个直白的问题逼到墙角：你的胜负判据，经得起两个学习者对它发起的合谋吗。</p><footer>—— 本课程对 FSP、PSRO、非传递性与机制设计诸线的收束口径</footer></div><p><a href="/llm/sgt-mechanism-design">上一课</a>完成视角翻转：从在博弈里学习的人换成设计博弈的人，并把「评测的可博弈性」列为头号工程问题。本课程到此收束。十课的路线是：理论映射、均衡与收敛、FSP、PSRO 铺理论地基（理论映射单元）；非传递性、棋牌教训、奖励塑形、辩论、协商、机制设计逐层搬到语言模型（语言模型的自博弈与收束单元）。收束课不添新对象，只做两件事：把十课压成一张决策地图，把「语言模型自博弈还没解决什么」钉成清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束课要回答的问题是使用侧的：读完一门理论课，工程师明天面对「要不要给我们的模型上自博弈」时，按什么顺序检查？主干课的<a href="/llm/self-play-lm">自博弈</a>给过做法面，本课程给的是条件面。逐课压下来，判据是三层。<strong>第一层，判据层</strong>：任务有没有外生、廉价、不可协商的胜负信号？有（数学、代码、可验证工具任务），进入第二层；没有，先解决判据——塑形、裁判或辩论都在这里排队，且每一项都要按<a href="/llm/sgt-reward-shaping">奖励塑形</a>那课做「关闭塑形的审计」。<strong>第二层，结构层</strong>：博弈是零和还是一般和？零和有收敛叙述可借（FSP 的时间平均、PSRO 的元均衡），一般和（协商、多模型竞争）要按 Crawford–Sobel 的封顶预想结果，塑形关系性指标。<strong>第三层，覆盖层</strong>：对手池是否覆盖循环维？按<a href="/llm/sgt-nontransitivity">非传递性</a>的结论，评测要报胜率向量，对手要按「对我胜率的凹陷」补入。</p><p>三层都不通过时，结论不是「自博弈无效」，而是「自博弈不是当前瓶颈」：先修判据或评测，比硬上自博弈便宜。这是把棋牌教训的<a href="/llm/sgt-chess-poker-lessons">环境四条件</a>读成决策规则的意思。</p><p><span class="marginnote">为什么这一步重要：判据层不过关就硬上自博弈，等于在没有裁判的球场上加练体能——练得越狠，越不知道自己是不是在进步。先花一行代码做「关塑形重评」的审计，比跑一周自博弈便宜得多，还能顺带检验塑形失真与裁判共谋。</span></p><h3 id="十课的压缩表" tabindex="-1">十课的压缩表 <a class="header-anchor" href="#十课的压缩表" aria-label="Permalink to &quot;十课的压缩表&quot;">​</a></h3><p>理论地基四课合一句话：自博弈把对手写进环境，均衡是审计工具不是训练目标，FSP 对历史频率响应、PSRO 对元均衡响应，二者的收敛保证都只在零和或良性元博弈里成立。语言模型五课合一句话：语言博弈天生不完美信息、一般和、判据自产，所以要么修判据（塑形、辩论），要么修结构（协商协议、机制设计），要么接受上限（非传递盲区永远补不完）。</p><p><span class="marginnote">一门课的最低限度可检验遗产：若你只记住一个动作，记住「关掉塑形、拿未塑形判据重评一次」——它同时检验塑形失真、裁判共谋与 Goodhart，成本一行代码。</span></p>',10)),(A(),B(l,null,{default:a(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q0%7B%22%E5%A4%96%E7%94%9F%E8%83%9C%E8%B4%9F%E5%88%A4%E6%8D%AE%EF%BC%9F%22%7D%20--%3E%7C%22%E6%97%A0%22%7C%20FIX%5B%22%E5%85%88%E4%BF%AE%E5%88%A4%E6%8D%AE%EF%BC%9A%E5%A1%91%E5%BD%A2%2F%E8%A3%81%E5%88%A4%2F%E8%BE%A9%E8%AE%BA%22%5D%0A%20%20Q0%20--%3E%7C%22%E6%9C%89%22%7C%20Q1%7B%22%E9%9B%B6%E5%92%8C%E5%8F%AF%E6%A8%A1%E6%8B%9F%EF%BC%9F%22%7D%0A%20%20FIX%20--%3E%20Q1%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20SP1%5B%22FSP%2FPSRO%20%E5%AE%B6%E6%97%8F%EF%BC%9A%E5%AF%B9%E6%89%8B%E6%B1%A0%E5%8A%A0%E5%85%83%E5%9D%87%E8%A1%A1%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%EF%BC%8C%E4%B8%80%E8%88%AC%E5%92%8C%22%7C%20SP2%5B%22%E5%85%B3%E7%B3%BB%E6%80%A7%E5%A1%91%E5%BD%A2%20%2B%20%E5%8D%8F%E8%AE%AE%E4%B8%8E%E6%9C%BA%E5%88%B6%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20SP1%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E8%83%9C%E7%8E%87%E5%90%91%E9%87%8F%E3%80%81%E5%87%B9%E9%99%B7%E5%AF%B9%E6%89%8B%E3%80%81%E5%85%B3%E5%A1%91%E5%BD%A2%E9%87%8D%E8%AF%84%22%5D%0A%20%20SP2%20--%3E%20AUD%0A%20%20AUD%20--%3E%20DEC%7B%22%E6%8C%87%E6%A0%87%E5%A1%8C%E6%96%B9%EF%BC%9F%22%7D%0A%20%20DEC%20--%3E%7C%22%E5%A1%8C%22%7C%20DIAG%5B%22%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%88%A4%E6%8D%AE%E9%94%99%2F%E5%A1%91%E5%BD%A2%E6%AD%AA%2F%E6%B1%A0%E7%9B%B2%E5%8C%BA%22%5D%0A%20%20DEC%20--%3E%7C%22%E7%A8%B3%22%7C%20SHIP%5B%22%E4%BA%A4%E4%BB%98%EF%BC%9A%E6%97%B6%E9%97%B4%E5%B9%B3%E5%9D%87%E6%88%96%E5%85%83%E5%9D%87%E8%A1%A1%E5%8A%A0%E6%9D%83%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>压缩成决策序列</strong>：十课不添新对象，压成三层判据按序检查——判据层（有无外生胜负）、结构层（零和可借收敛叙述、一般和按封顶预期）、覆盖层（对手池补循环维），每层不通过就换动作而不是换超参。第二件方法是统一命名：把各课方法化约为「按什么分布取环境」——FSP 按历史频率、PSRO 按元均衡、辩论取最强反方；审计钉死次序：关塑形、换判据、补盲区，一步一评。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>十课在机制层的公共资产是同一个视角：<strong>对手分布就是环境设计</strong>。主干课的做法面（换对手、留池子、迭代自博弈）在这一视角下获得统一解释——FSP 是「按历史频率取环境」，PSRO 是「按元均衡取环境」，AlphaStar 联赛是「专职挖掘环境盲区」，SPIN 是「环境退化为上一轮自身」，辩论是「环境取最强反方」，机制设计是「干脆设计环境」。方法间的取舍由此化约为：你的判据与预算，配得起哪种环境复杂度。</p><p>这张谱系图回答的问题是：同一个「取环境」视角下，各方法到底差在哪一环。</p>',5)),(A(),B(l,null,{default:a(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E5%85%AC%E5%85%B1%E6%9C%BA%E5%88%B6%EF%BC%9A%E5%AF%B9%E6%89%8B%E5%88%86%E5%B8%83%20%3D%20%E7%8E%AF%E5%A2%83%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20CORE%20--%3E%20FSP%5B%22FSP%EF%BC%9A%E6%8C%89%E5%8E%86%E5%8F%B2%E9%A2%91%E7%8E%87%E5%8F%96%22%5D%0A%20%20CORE%20--%3E%20PSRO%5B%22PSRO%EF%BC%9A%E6%8C%89%E5%85%83%E5%9D%87%E8%A1%A1%E5%8F%96%22%5D%0A%20%20CORE%20--%3E%20LGE%5B%22%E8%81%94%E8%B5%9B%EF%BC%9A%E4%B8%93%E8%81%8C%E6%8C%96%E7%8E%AF%E5%A2%83%E7%9B%B2%E5%8C%BA%22%5D%0A%20%20CORE%20--%3E%20SPIN%5B%22SPIN%EF%BC%9A%E5%8F%96%E4%B8%8A%E4%B8%80%E8%BD%AE%E8%87%AA%E8%BA%AB%22%5D%0A%20%20CORE%20--%3E%20DB%5B%22%E8%BE%A9%E8%AE%BA%EF%BC%9A%E5%8F%96%E6%9C%80%E5%BC%BA%E5%8F%8D%E6%96%B9%22%5D%0A%20%20CORE%20--%3E%20MD%5B%22%E6%9C%BA%E5%88%B6%E8%AE%BE%E8%AE%A1%EF%BC%9A%E7%9B%B4%E6%8E%A5%E8%AE%BE%E8%AE%A1%E7%8E%AF%E5%A2%83%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p>第二件公共资产是审计顺序。本课程反复出现的失败模式——追最新对手过拟合、塑形搬走均衡、裁判共谋、排行榜 Goodhart、协议变共谋——共享同一结构：<strong>优化目标与评价目标脱钩</strong>。审计有通用次序：先关塑形、再换判据、再补盲区对手，一步一评，定位脱钩发生在哪一层。跳步的诊断会把「判据错了」误治成「训练不够」。</p><p><span class="marginnote">直觉类比：优化是平时练习，评价是期末考试。「目标脱钩」就是刷的题和考的题不是一套——练得再熟，考试照样露馅。审计的次序就是逐层对答案：先确认练习卷（塑形）没错题，再确认考卷（判据）没跑偏，最后确认题库（对手池）覆盖了所有题型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>钉下这门课没解决、也不装作解决了的清单。其一，<strong>可利用度不可算</strong>：语言博弈的 exploitability 没有算法入口，一切「接近均衡」的说法在语言模型上都是比喻，实证只能靠代理指标；其二，<strong>均衡选择无理论</strong>：一般和博弈多均衡时选哪个，语言场景连问题描述都未成形；其三，<strong>判据自产的循环</strong>：裁判、评测、协议都由模型充当时，系统在测自己，本课程给的是审计手法（隔离、关塑形、换域复测），不是解；其四，<strong>效用可塑</strong>：规则进权重还是进环境的双轨题没有答案。这四条不否定已写的内容，它们定义的是下一轮深钻的入口。</p><p><span class="marginnote">术语翻译：「判据自产」就是考卷由考生自己出、阅卷也由考生自己批。模型既当裁判又当选手时，系统在测自己——分数再高也只说明它学会了让自己满意。审计手法（换域、隔离、关塑形）相当于请外校出题，能缓解但消不掉这个循环。</span></p><p>后课默认：再遇到「自博弈」「对手池」「辩论训练」这些词，你会先问判据、结构、覆盖三层，而不是直接问超参数。本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>十课压缩为三层判据：判据层（有无外生胜负）、结构层（零和可借收敛叙述，一般和按协商封顶预期）、覆盖层（对手池补循环维）。</li><li>机制层公共资产：对手分布即环境设计；各方法化约为「按什么分布取环境」。</li><li>失败模式共享结构——优化目标与评价目标脱钩；审计次序：关塑形、换判据、补盲区，一步一评。</li><li>未解清单：可利用度不可算、均衡选择无理论、判据自产的循环、效用可塑下的机制双轨题。</li><li>语言自博弈的可行域近 Hanabi 而非围棋：先修判据与约定，再谈强度。</li><li>出处：本课程各课口径的总收束；理论线见 Brown 1951、Robinson 1951、Lanctot 等 2017、Balduzzi 等 2019、Czarnecki 等 2020，语言线见 Heinrich 与 Silver 2016、Irving 等 2018、Bakhtin 等 2022、Chen 等 2024。</li></ul>',8))])}const P=o(C,[["render",p]]);export{g as __pageData,P as default};
